def is_simple_power(x, n):
    """Returns True if x is a simple power of n, and False otherwise."""
    if n == 0:
        return x == 1  # 0^int is not valid except when x = 1 as 0^0 is often defined as 1
    if x == 1:
        return True  # Any number to the power of 0 is 1
    if n == 1:
        return x == 1  # 1^int is 1 only if int is 0, which means x should be 1

    power = 1
    while power < x:
        power *= n

    return power == x
